/* ================================================
   GHN ID Card Generator – app.js
   ================================================ */

// ─── State ──────────────────────────────────────
const state = {
  employees: [],   // [{ id, name, title, msnv, photoDataUrl }]
  nextId: 1,
  currentPhotoDataUrl: null,
  zoom: 70,
};

// ─── DOM refs ────────────────────────────────────
const $ = id => document.getElementById(id);
const inpName       = $('inp-name');
const inpTitle      = $('inp-title');
const inpId         = $('inp-id');
const inpPhoto      = $('inp-photo');
const photoDropZone = $('photo-drop-zone');
const photoPlaceholder = $('photo-placeholder');
const photoPreview  = $('photo-preview');
const btnRemovePhoto = $('btn-remove-photo');
const btnAdd        = $('btn-add');
const inpExcel      = $('inp-excel');
const excelDropZone = $('excel-drop-zone');
const btnDownloadTemplate = $('btn-download-template');
const employeeList  = $('employee-list');
const countEl       = $('count');
const btnClearAll   = $('btn-clear-all');
const previewPages  = $('preview-pages');
const emptyPreview  = $('empty-preview');
const zoomSlider    = $('zoom-slider');
const zoomValue     = $('zoom-value');
const btnExportPng  = $('btn-export-png');
const btnExportPdf  = $('btn-export-pdf');
const idcardToastEl = $('idcard-toast');
const loadingOverlay = $('idcard-loading-overlay');
const loadingText   = $('idcard-loading-text');

// ─── Toast ───────────────────────────────────────
let toastTimer = null;
function showToast(msg, type = 'success', duration = 3000) {
  idcardToastEl.textContent = msg;
  idcardToastEl.className = `toast ${type}`;
  idcardToastEl.classList.remove('hidden');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => { idcardToastEl.classList.add('hidden'); }, duration);
}

// ─── Loading ─────────────────────────────────────
function showLoading(msg = 'Đang xử lý...') { loadingText.textContent = msg; loadingOverlay.classList.remove('hidden'); }
function hideLoading() { loadingOverlay.classList.add('hidden'); }

// ─── Photo upload ────────────────────────────────
function setPhoto(dataUrl) {
  state.currentPhotoDataUrl = dataUrl;
  photoPreview.src = dataUrl;
  photoPreview.classList.remove('hidden');
  photoPlaceholder.style.display = 'none';
  btnRemovePhoto.classList.remove('hidden');
}
function clearPhoto() {
  state.currentPhotoDataUrl = null;
  photoPreview.src = '';
  photoPreview.classList.add('hidden');
  photoPlaceholder.style.display = '';
  btnRemovePhoto.classList.add('hidden');
  inpPhoto.value = '';
}
function readFileAsDataUrl(file) {
  return new Promise((res, rej) => {
    const r = new FileReader();
    r.onload = e => res(e.target.result);
    r.onerror = rej;
    r.readAsDataURL(file);
  });
}

inpPhoto.addEventListener('click', e => e.stopPropagation());
inpPhoto.addEventListener('change', async () => {
  if (inpPhoto.files && inpPhoto.files[0]) {
    const du = await readFileAsDataUrl(inpPhoto.files[0]);
    setPhoto(du);
    inpPhoto.value = '';
  }
});

btnRemovePhoto.addEventListener('click', e => { e.stopPropagation(); clearPhoto(); });

// drag-drop photo
photoDropZone.addEventListener('click', (e) => {
  if (e.target === btnRemovePhoto || btnRemovePhoto.contains(e.target)) return;
  if (!state.currentPhotoDataUrl) inpPhoto.click();
});
photoDropZone.addEventListener('dragenter', e => { e.preventDefault(); e.stopPropagation(); photoDropZone.classList.add('drag-over'); });
photoDropZone.addEventListener('dragover',  e => { e.preventDefault(); e.stopPropagation(); photoDropZone.classList.add('drag-over'); });
photoDropZone.addEventListener('dragleave', (e) => {
  if (e.relatedTarget && photoDropZone.contains(e.relatedTarget)) return;
  photoDropZone.classList.remove('drag-over');
});
photoDropZone.addEventListener('drop', async e => {
  e.preventDefault();
  e.stopPropagation();
  photoDropZone.classList.remove('drag-over');
  const files = e.dataTransfer ? e.dataTransfer.files : null;
  if (files && files[0] && files[0].type.startsWith('image/')) {
    const du = await readFileAsDataUrl(files[0]);
    setPhoto(du);
  }
});

// ─── Add employee ────────────────────────────────
function addEmployee({ name, title, msnv, photo }) {
  if (!name.trim()) { showToast('⚠️ Vui lòng nhập họ và tên', 'error'); return false; }
  if (!title.trim()) { showToast('⚠️ Vui lòng nhập chức danh', 'error'); return false; }
  state.employees.push({
    id: state.nextId++,
    name: name.trim(),
    title: title.trim(),
    msnv: msnv.trim() || '',
    photo: photo || null,
  });
  return true;
}

btnAdd.addEventListener('click', () => {
  const ok = addEmployee({
    name: inpName.value,
    title: inpTitle.value,
    msnv: inpId.value,
    photo: state.currentPhotoDataUrl,
  });
  if (!ok) return;
  // reset form
  inpName.value = '';
  inpTitle.value = '';
  inpId.value = '';
  clearPhoto();
  renderAll();
  showToast('✅ Đã thêm nhân viên');
  inpName.focus();
});

// Enter key on inputs
[inpName, inpTitle, inpId].forEach(inp => {
  inp.addEventListener('keydown', e => { if (e.key === 'Enter') btnAdd.click(); });
});

// ─── Delete / Clear ──────────────────────────────
function deleteEmployee(id) {
  state.employees = state.employees.filter(e => e.id !== id);
  renderAll();
}

btnClearAll.addEventListener('click', () => {
  if (!state.employees.length) return;
  if (!confirm(`Xóa tất cả ${state.employees.length} nhân viên?`)) return;
  state.employees = [];
  renderAll();
  showToast('Đã xóa tất cả', 'info');
});

// ─── Render employee list ────────────────────────
function initials(name) {
  return name.split(' ').map(w => w[0] || '').join('').toUpperCase().slice(0, 2);
}

function renderEmployeeList() {
  countEl.textContent = state.employees.length;
  if (!state.employees.length) {
    employeeList.innerHTML = `
      <div class="empty-state">
        <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#ddd" stroke-width="1.2"><circle cx="12" cy="8" r="4"/><path d="M4 20c0-4 3.6-7 8-7s8 3 8 7"/></svg>
        <p>Chưa có nhân viên nào</p>
      </div>`;
    return;
  }
  employeeList.innerHTML = state.employees.map(emp => `
    <div class="employee-item" data-id="${emp.id}">
      <div class="employee-thumb">
        ${emp.photo
          ? `<img src="${emp.photo}" alt="${emp.name}" />`
          : initials(emp.name)}
      </div>
      <div class="employee-info">
        <div class="emp-name">${escHtml(emp.name)}</div>
        <div class="emp-sub">${escHtml(emp.title)}${emp.msnv ? ' · ' + escHtml(emp.msnv) : ''}</div>
      </div>
      <button class="btn-delete-item" data-id="${emp.id}" title="Xóa">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/></svg>
      </button>
    </div>
  `).join('');

  employeeList.querySelectorAll('.btn-delete-item').forEach(btn => {
    btn.addEventListener('click', e => {
      e.stopPropagation();
      deleteEmployee(+btn.dataset.id);
    });
  });
}

function escHtml(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

// ─── Build card HTML ─────────────────────────────
function buildCardHTML(emp) {
  const photoHTML = emp.photo
    ? `<img src="${emp.photo}" alt="${escHtml(emp.name)}" onerror="this.onerror=null; this.parentElement.innerHTML='<div class=\\'card-photo-placeholder\\'><span style=\\'color:red; font-size:10px;\\'>Lỗi truy cập ảnh<br>(Check quyền link)</span></div>';" />`
    : `<div class="card-photo-placeholder">
        <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="#90b8c8" stroke-width="1"><circle cx="12" cy="8" r="4"/><path d="M4 20c0-4 3.6-7 8-7s8 3 8 7"/></svg>
        <span>Ảnh</span>
       </div>`;

  return `
    <div class="id-card-wrap">
      <div class="id-card">
        <div class="id-card-inner-white">
          <div class="card-header">
            <img src="data:image/png;base64," alt="GHN Logo" class="card-logo-img" />
          </div>

          <div class="card-photo-area">
            <div class="card-photo-wrapper">
              <div class="card-photo-oval">${photoHTML}</div>
            </div>
          </div>

          <div class="card-info">
            <div class="card-name">${escHtml(emp.name)}</div>
            <div class="card-position">${escHtml(emp.title)}</div>
            ${emp.msnv ? `<div class="card-msnv">${escHtml(emp.msnv)}</div>` : ''}
          </div>

          <div class="card-footer">
            <span class="card-footer-text">A member of</span>
            <span class="card-footer-brand">SC<span class="scommerce-o"><span class="scommerce-o-dot"></span></span>MMERCE</span>
          </div>
        </div>
      </div>
    </div>`;
}

// ─── Render preview pages ────────────────────────
const CARDS_PER_PAGE = 9;

function renderPreview() {
  if (!state.employees.length) {
    previewPages.innerHTML = '';
    emptyPreview.style.display = '';
    return;
  }
  emptyPreview.style.display = 'none';

  const pages = [];
  for (let i = 0; i < state.employees.length; i += CARDS_PER_PAGE) {
    pages.push(state.employees.slice(i, i + CARDS_PER_PAGE));
  }

  previewPages.innerHTML = pages.map((pageEmps, pi) => {
    // Fill empty slots
    const slots = [...pageEmps];
    while (slots.length < CARDS_PER_PAGE) slots.push(null);

    const cardsHtml = slots.map(emp =>
      emp ? buildCardHTML(emp) : '<div class="id-card-wrap"><div style="width:204px;height:320px;"></div></div>'
    ).join('');

    return `<div class="a4-page" id="a4-page-${pi}" style="transform:scale(${state.zoom/100})">${cardsHtml}</div>`;
  }).join('');
}

function renderAll() {
  renderEmployeeList();
  renderPreview();
}

// ─── Zoom ────────────────────────────────────────
zoomSlider.addEventListener('input', () => {
  state.zoom = +zoomSlider.value;
  zoomValue.textContent = state.zoom + '%';
  document.querySelectorAll('.a4-page').forEach(p => {
    p.style.transform = `scale(${state.zoom / 100})`;
  });
});

// ─── Import Excel / CSV ──────────────────────────
function normalizeHeader(h) {
  return String(h).toLowerCase().trim()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ');
}

function findCol(headers, ...candidates) {
  const norm = headers.map(normalizeHeader);
  for (const c of candidates) {
    const idx = norm.findIndex(h => h.includes(normalizeHeader(c)));
    if (idx !== -1) return idx;
  }
  return -1;
}

async function importExcelFile(file) {
  const data = await file.arrayBuffer();
  const wb = XLSX.read(data, { type: 'array' });
  const ws = wb.Sheets[wb.SheetNames[0]];
  const rows = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });
  if (rows.length < 2) { showToast('File không có dữ liệu', 'error'); return; }

  const headers = rows[0];
  const nameCol  = findCol(headers, 'ho ten', 'ho va ten', 'name', 'ten', 'fullname');
  const titleCol = findCol(headers, 'chuc danh', 'chuc vu', 'position', 'title', 'chức danh', 'chức vụ');
  const msnvCol  = findCol(headers, 'msnv', 'ma so nhan vien', 'ma nhan vien', 'employee id', 'id', 'ma nv');
  const photoCol = findCol(headers, 'hinh anh', 'anh', 'photo', 'avatar', 'link', 'url', 'hình ảnh');

  if (nameCol === -1) { showToast('Không tìm thấy cột Họ tên trong file', 'error'); return; }

  let added = 0;
  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    const name  = String(row[nameCol] || '').trim();
    const title = titleCol !== -1 ? String(row[titleCol] || '').trim() : '';
    const msnv  = msnvCol  !== -1 ? String(row[msnvCol]  || '').trim() : '';
    let photo   = photoCol !== -1 ? String(row[photoCol] || '').trim() : '';
    
    // Xử lý link Google Drive (chuyển sang dạng thẻ img có thể đọc được nếu là link chia sẻ)
    if (photo.includes('drive.google.com/file/d/')) {
      const match = photo.match(/file\/d\/([a-zA-Z0-9_-]+)/);
      if (match) {
        photo = `https://drive.google.com/uc?export=view&id=${match[1]}`;
      }
    }

    if (!name) continue;
    addEmployee({ name, title: title || 'Nhân viên', msnv, photo: photo || null });
    added++;
  }

  renderAll();
  showToast(`✅ Đã import ${added} nhân viên từ file`);
}

inpExcel.addEventListener('click', e => e.stopPropagation());
inpExcel.addEventListener('change', () => {
  if (inpExcel.files && inpExcel.files[0]) {
    importExcelFile(inpExcel.files[0]);
    inpExcel.value = '';
  }
});

excelDropZone.addEventListener('click', () => inpExcel.click());
excelDropZone.addEventListener('dragenter', e => { e.preventDefault(); e.stopPropagation(); excelDropZone.classList.add('drag-over'); });
excelDropZone.addEventListener('dragover',  e => { e.preventDefault(); e.stopPropagation(); excelDropZone.classList.add('drag-over'); });
excelDropZone.addEventListener('dragleave', (e) => {
  if (e.relatedTarget && excelDropZone.contains(e.relatedTarget)) return;
  excelDropZone.classList.remove('drag-over');
});
excelDropZone.addEventListener('drop', e => {
  e.preventDefault();
  e.stopPropagation();
  excelDropZone.classList.remove('drag-over');
  const files = e.dataTransfer ? e.dataTransfer.files : null;
  if (files && files[0]) {
    importExcelFile(files[0]);
  }
});

// ─── Bulk Image Upload ───────────────────────────
const inpBulkImages = document.getElementById('inp-bulk-images');
const bulkImageDropZone = document.getElementById('bulk-image-drop-zone');

async function processBulkImages(files) {
  if (!files || files.length === 0) return;
  if (!state.employees.length) {
    showToast('Vui lòng tải danh sách Excel trước', 'error');
    return;
  }

  showLoading(`Đang xử lý ${files.length} ảnh...`);
  let matchCount = 0;

  const removeExt = (fn) => fn.substring(0, fn.lastIndexOf('.')) || fn;
  const norm = (str) => String(str || '').normalize('NFC').toLowerCase().trim().replace(/\s+/g, ' ');
  const normNoAccent = (str) => norm(str).normalize('NFD').replace(/[\u0300-\u036f]/g, '');

  for (const file of Array.from(files)) {
    if (!file.type.startsWith('image/')) continue;
    const rawName = removeExt(file.name).trim();
    const nName = norm(rawName);
    const nNoAccent = normNoAccent(rawName);

    // Tìm nhân viên có Họ Tên hoặc MSNV trùng với tên file (hỗ trợ cả có dấu và không dấu)
    const emp = state.employees.find(e => {
      const eName = norm(e.name);
      const eNameNoAccent = normNoAccent(e.name);
      const eMsnv = norm(e.msnv);
      return (eName && (eName === nName || eNameNoAccent === nNoAccent)) ||
             (eMsnv && (eMsnv === nName || eMsnv === nNoAccent));
    });

    if (emp) {
      try {
        emp.photo = await readFileAsDataUrl(file);
        matchCount++;
      } catch (err) {
        console.error('Lỗi đọc file ảnh', file.name, err);
      }
    }
  }

  renderAll();
  hideLoading();
  
  if (matchCount > 0) {
    showToast(`✅ Đã ghép nối thành công ${matchCount} ảnh!`);
  } else {
    showToast('⚠️ Không tìm thấy nhân viên có Họ tên hoặc MSNV trùng với tên ảnh', 'error');
  }
}

if (inpBulkImages && bulkImageDropZone) {
  inpBulkImages.addEventListener('click', e => e.stopPropagation());
  inpBulkImages.addEventListener('change', () => {
    if (inpBulkImages.files && inpBulkImages.files.length > 0) {
      processBulkImages(inpBulkImages.files);
      inpBulkImages.value = '';
    }
  });

  bulkImageDropZone.addEventListener('click', () => inpBulkImages.click());
  bulkImageDropZone.addEventListener('dragenter', e => { e.preventDefault(); e.stopPropagation(); bulkImageDropZone.classList.add('drag-over'); });
  bulkImageDropZone.addEventListener('dragover',  e => { e.preventDefault(); e.stopPropagation(); bulkImageDropZone.classList.add('drag-over'); });
  bulkImageDropZone.addEventListener('dragleave', (e) => {
    if (e.relatedTarget && bulkImageDropZone.contains(e.relatedTarget)) return;
    bulkImageDropZone.classList.remove('drag-over');
  });
  bulkImageDropZone.addEventListener('drop', e => {
    e.preventDefault();
    e.stopPropagation();
    bulkImageDropZone.classList.remove('drag-over');
    const files = e.dataTransfer ? e.dataTransfer.files : null;
    if (files && files.length > 0) {
      processBulkImages(files);
    }
  });
}

