window.addEventListener('dragover', e => e.preventDefault());
window.addEventListener('drop', e => e.preventDefault());

// ─── Download CSV template ───────────────────────
btnDownloadTemplate.addEventListener('click', () => {
  const csv = 'Họ tên,Chức danh,MSNV\nNguyễn Văn A,Nhân viên giao hàng,GHN-0001\nTrần Thị B,Trưởng nhóm,GHN-0002';
  const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = 'mau_danh_sach_nhan_vien.csv';
  a.click(); URL.revokeObjectURL(url);
});

// ─── Export helpers ──────────────────────────────
async function capturePages() {
  const pages = document.querySelectorAll('.a4-page');
  const canvases = [];
  for (const page of pages) {
    const origTransform = page.style.transform;
    page.style.transform = 'scale(1)';
    const canvas = await html2canvas(page, {
      scale: 2,
      useCORS: true,
      allowTaint: false,
      backgroundColor: '#ffffff',
      logging: false,
      width: 793,
      height: 1122,
    });
    page.style.transform = origTransform;
    canvases.push(canvas);
  }
  return canvases;
}

// ─── Export PNG ──────────────────────────────────
btnExportPng.addEventListener('click', async () => {
  if (!state.employees.length) { showToast('Chưa có nhân viên nào', 'error'); return; }
  showLoading('Đang tạo ảnh PNG...');
  try {
    const canvases = await capturePages();
    canvases.forEach((canvas, i) => {
      const url = canvas.toDataURL('image/png');
      const a = document.createElement('a');
      a.href = url;
      a.download = canvases.length === 1 ? 'the_nhan_vien.png' : `the_nhan_vien_trang_${i+1}.png`;
      a.click();
    });
    showToast(`✅ Đã xuất ${canvases.length} ảnh PNG`);
  } catch(e) {
    showToast('Lỗi khi xuất PNG: ' + e.message, 'error');
  } finally {
    hideLoading();
  }
});

// ─── Export PDF ──────────────────────────────────
btnExportPdf.addEventListener('click', async () => {
  if (!state.employees.length) { showToast('Chưa có nhân viên nào', 'error'); return; }
  showLoading('Đang tạo file PDF...');
  try {
    const { jsPDF } = window.jspdf;
    // A4: 210 x 297 mm
    const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
    const canvases = await capturePages();

    canvases.forEach((canvas, i) => {
      if (i > 0) pdf.addPage();
      const imgData = canvas.toDataURL('image/jpeg', 0.95);
      pdf.addImage(imgData, 'JPEG', 0, 0, 210, 297);
    });

    pdf.save('the_nhan_vien_GHN.pdf');
    showToast(`✅ Đã xuất PDF (${canvases.length} trang)`);
  } catch(e) {
    showToast('Lỗi khi xuất PDF: ' + e.message, 'error');
  } finally {
    hideLoading();
  }
});

