// ─── Layout Controls ──────────────────────────────
const rootStyle = document.documentElement.style;

const layoutControls = [
  { id: 'ctrl-logo-scale', varName: '--logo-scale', suffix: '' },
  { id: 'ctrl-logo-y', varName: '--logo-y', suffix: 'px' },
  { id: 'ctrl-avatar-scale', varName: '--avatar-scale', suffix: '' },
  { id: 'ctrl-avatar-y', varName: '--avatar-y', suffix: 'px' },
  { id: 'ctrl-info-scale', varName: '--info-scale', suffix: '' },
  { id: 'ctrl-info-y', varName: '--info-y', suffix: 'px' },
  { id: 'ctrl-footer-y', varName: '--footer-y', suffix: 'px' },
];

function updateLayoutVar(ctrl, value) {
  rootStyle.setProperty(ctrl.varName, value + ctrl.suffix);
  
  if (ctrl.varName === '--avatar-scale' || ctrl.varName === '--avatar-y') {
    const scaleEl = document.getElementById('ctrl-avatar-scale');
    const yEl = document.getElementById('ctrl-avatar-y');
    const avatarScale = scaleEl ? parseFloat(scaleEl.value) : 1;
    const avatarY = yEl ? parseFloat(yEl.value) : 0;
    
    const size = 166 * avatarScale;
    const marginTop = (-size / 2) + avatarY;
    const marginLeft = (-size / 2);
    
    rootStyle.setProperty('--avatar-width-px', size + 'px');
    rootStyle.setProperty('--avatar-height-px', size + 'px');
    rootStyle.setProperty('--avatar-mt-px', marginTop + 'px');
    rootStyle.setProperty('--avatar-ml-px', marginLeft + 'px');
  }

  if (ctrl.varName === '--logo-scale' || ctrl.varName === '--logo-y') {
    const scaleEl = document.getElementById('ctrl-logo-scale');
    const yEl = document.getElementById('ctrl-logo-y');
    const logoScale = scaleEl ? parseFloat(scaleEl.value) : 1;
    const logoY = yEl ? parseFloat(yEl.value) : 0;
    
    const width = 145 * logoScale;
    const marginTop = -5 + logoY;
    
    rootStyle.setProperty('--logo-width-px', width + 'px');
    rootStyle.setProperty('--logo-mt-px', marginTop + 'px');
  }

  if (ctrl.varName === '--info-scale' || ctrl.varName === '--info-y') {
    const scaleEl = document.getElementById('ctrl-info-scale');
    const yEl = document.getElementById('ctrl-info-y');
    const infoScale = scaleEl ? parseFloat(scaleEl.value) : 1;
    const infoY = yEl ? parseFloat(yEl.value) : 0;
    
    rootStyle.setProperty('--info-scale-val', infoScale);
    rootStyle.setProperty('--info-mt-px', infoY + 'px');
  }

  if (ctrl.varName === '--footer-y') {
    const yEl = document.getElementById('ctrl-footer-y');
    const footerY = yEl ? parseFloat(yEl.value) : 0;
    rootStyle.setProperty('--footer-mb-px', -footerY + 'px');
  }
}

layoutControls.forEach(ctrl => {
  const el = document.getElementById(ctrl.id);
  if (el) {
    // Load from localStorage if exists
    const saved = localStorage.getItem('layout-' + ctrl.id);
    if (saved !== null) {
      el.value = saved;
    }
    
    el.addEventListener('input', (e) => {
      updateLayoutVar(ctrl, e.target.value);
      localStorage.setItem('layout-' + ctrl.id, e.target.value);
    });
    
    // Init values for all layout vars so they apply immediately
    updateLayoutVar(ctrl, el.value);
  }
});

const btnResetLayout = document.getElementById('btn-reset-layout');
if (btnResetLayout) {
  btnResetLayout.addEventListener('click', () => {
    layoutControls.forEach(ctrl => {
      const el = document.getElementById(ctrl.id);
      if (el) {
        el.value = el.defaultValue;
        updateLayoutVar(ctrl, el.value);
        localStorage.removeItem('layout-' + ctrl.id);
      }
    });
  });
}
